// Express.js - Add CSP headers via helmet middleware
const express = require('express');
const helmet = require('helmet');
const crypto = require('crypto');

const app = express();

// Method 1: Use helmet for CSP (recommended)
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", (req, res) => `'nonce-${res.locals.cspNonce}'`],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      fontSrc: ["'self'", "data:"],
      connectSrc: ["'self'"],
      frameAncestors: ["'none'"],
      baseUri: ["'self'"],
      formAction: ["'self'"],
      objectSrc: ["'none'"],
    },
    // Use report-only mode for testing
    // reportOnly: true,
  })
);

// Generate nonce for each request
app.use((req, res, next) => {
  res.locals.cspNonce = crypto.randomBytes(16).toString('base64');
  next();
});

// Method 2: Manual CSP header (if not using helmet)
app.use((req, res, next) => {
  const nonce = crypto.randomBytes(16).toString('base64');
  res.locals.cspNonce = nonce;

  const cspPolicy = [
    "default-src 'self'",
    `script-src 'self' 'nonce-${nonce}'`,
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data: https:",
    "font-src 'self' data:",
    "connect-src 'self'",
    "frame-ancestors 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "object-src 'none'",
  ].join('; ');

  res.setHeader('Content-Security-Policy', cspPolicy);
  next();
});

// In your views (EJS example):
// <script nonce="<%= cspNonce %>">...</script>

app.get('/', (req, res) => {
  res.send(`
    <!DOCTYPE html>
    <html>
      <head>
        <title>CSP Protected</title>
      </head>
      <body>
        <h1>Content Security Policy Enabled</h1>
        <script nonce="${res.locals.cspNonce}">
          console.log('This script is allowed by CSP nonce');
        </script>
      </body>
    </html>
  `);
});

app.listen(3000);

