// Mocha/Chai test for CSP header
const request = require('supertest');
const { expect } = require('chai');
const app = require('../app');

describe('CSP Header Tests', () => {
  it('should have Content-Security-Policy header', (done) => {
    request(app)
      .get('/')
      .expect(200)
      .expect('Content-Security-Policy', /default-src 'self'/)
      .end(done);
  });

  it('should not allow unsafe-inline for scripts', (done) => {
    request(app)
      .get('/')
      .end((err, res) => {
        if (err) return done(err);

        const csp = res.headers['content-security-policy'];
        expect(csp).to.exist;

        // Parse script-src directive
        const scriptSrcMatch = csp.match(/script-src ([^;]+)/);
        expect(scriptSrcMatch).to.exist;

        const scriptSrc = scriptSrcMatch[1];
        expect(scriptSrc).to.not.include("'unsafe-inline'");

        done();
      });
  });

  it('should include nonce for script-src', (done) => {
    request(app)
      .get('/')
      .end((err, res) => {
        if (err) return done(err);

        const csp = res.headers['content-security-policy'];
        expect(csp).to.match(/'nonce-[A-Za-z0-9+/=]+'/); 

        done();
      });
  });

  it('should block object-src', (done) => {
    request(app)
      .get('/')
      .end((err, res) => {
        if (err) return done(err);

        const csp = res.headers['content-security-policy'];
        expect(csp).to.include("object-src 'none'");

        done();
      });
  });
});

