// xUnit test for CSP header
using Xunit;
using Microsoft.AspNetCore.Mvc.Testing;
using System.Net.Http;
using System.Threading.Tasks;
using System.Linq;

public class CspHeaderTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public CspHeaderTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Should_Have_Csp_Header()
    {
        var response = await _client.GetAsync("/");

        Assert.True(response.Headers.Contains("Content-Security-Policy"),
            "Response should contain Content-Security-Policy header");
    }

    [Fact]
    public async Task Csp_Should_Include_Default_Src_Self()
    {
        var response = await _client.GetAsync("/");
        var cspHeader = response.Headers.GetValues("Content-Security-Policy").First();

        Assert.Contains("default-src 'self'", cspHeader);
    }

    [Fact]
    public async Task Csp_Should_Not_Allow_Unsafe_Inline_Scripts()
    {
        var response = await _client.GetAsync("/");
        var cspHeader = response.Headers.GetValues("Content-Security-Policy").First();

        // Extract script-src directive
        var scriptSrc = ExtractDirective(cspHeader, "script-src");

        Assert.DoesNotContain("'unsafe-inline'", scriptSrc);
    }

    [Fact]
    public async Task Csp_Should_Include_Nonce_For_Scripts()
    {
        var response = await _client.GetAsync("/");
        var cspHeader = response.Headers.GetValues("Content-Security-Policy").First();

        Assert.Matches(@"'nonce-[A-Za-z0-9+/=]+'", cspHeader);
    }

    private string ExtractDirective(string csp, string directive)
    {
        var directives = csp.Split(';');
        var target = directives.FirstOrDefault(d => d.Trim().StartsWith(directive));
        return target?.Trim() ?? string.Empty;
    }
}

