# Nginx - Add CSP header configuration
# /etc/nginx/sites-available/your-site or /etc/nginx/nginx.conf

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name your-domain.com;

    # Basic CSP policy (static, no nonces)
    add_header Content-Security-Policy 
        "default-src 'self'; 
        script-src 'self'; 
        style-src 'self' 'unsafe-inline'; 
        img-src 'self' data: https:; 
        font-src 'self' data:; 
        connect-src 'self'; 
        frame-ancestors 'none'; 
        base-uri 'self'; 
        form-action 'self'; 
        object-src 'none'" always;

    # Report-Only mode for testing
    # add_header Content-Security-Policy-Report-Only 
    #     "default-src 'self'; ..." always;

    # Other security headers (recommended)
    add_header X-Frame-Options "DENY" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-XSS-Protection "1; mode=block" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    location / {
        # Your application config
        proxy_pass http://backend;

        # Preserve headers
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
}

