// Selenium test for CSP header validation
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.openqa.selenium.logging.LogEntries;
import org.openqa.selenium.logging.LogEntry;
import org.openqa.selenium.logging.LogType;
import org.testng.annotations.Test;
import org.testng.Assert;
import java.util.List;

public class CspHeaderTest {

    @Test
    public void verifyCspHeaderPresent() {
        ChromeOptions options = new ChromeOptions();
        options.setCapability("goog:loggingPrefs", 
            Map.of("browser", "ALL", "performance", "ALL"));

        WebDriver driver = new ChromeDriver(options);

        try {
            driver.get("https://your-domain.com");

            // Get performance logs to check response headers
            LogEntries logs = driver.manage().logs().get(LogType.PERFORMANCE);

            boolean cspHeaderFound = false;
            for (LogEntry entry : logs) {
                if (entry.getMessage().contains("Content-Security-Policy")) {
                    cspHeaderFound = true;
                    break;
                }
            }

            Assert.assertTrue(cspHeaderFound, 
                "Content-Security-Policy header should be present");

        } finally {
            driver.quit();
        }
    }

    @Test
    public void verifyNoCspViolations() {
        ChromeDriver driver = new ChromeDriver();

        try {
            driver.get("https://your-domain.com");

            // Get browser console logs
            LogEntries logs = driver.manage().logs().get(LogType.BROWSER);

            List<String> cspViolations = new ArrayList<>();
            for (LogEntry entry : logs) {
                String message = entry.getMessage();
                if (message.contains("Content Security Policy") || 
                    message.contains("CSP")) {
                    cspViolations.add(message);
                }
            }

            Assert.assertTrue(cspViolations.isEmpty(), 
                "No CSP violations should occur. Found: " + cspViolations);

        } finally {
            driver.quit();
        }
    }

