        WebDriver driver = new ChromeDriver();

        try {
            // Test login
            driver.get("https://your-domain.com/login");
            // ... perform login ...
            Assert.assertTrue(driver.getCurrentUrl().contains("dashboard"), 
                "Login should succeed with CSP enabled");

            // Test form submission
            driver.get("https://your-domain.com/contact");
            // ... submit form ...
            Assert.assertTrue(driver.getPageSource().contains("Thank you"), 
                "Form submission should work with CSP");

            // Test AJAX
            driver.get("https://your-domain.com");
            // ... trigger AJAX request ...
